<template>
  <div class="input-group" v-if="!submitted">
        <input type="text" class="form-control me-2" placeholder="Enter Rejection Reason" v-model="description">
        <button class="btn btn-primary" @click="saveRejection()" :disabled="loading">
            <span v-if="loading" v-html="loadingSpinner()"></span>
            <span v-else>Submit</span>
        </button>
  </div>
</template>

<script setup>
import { ref, onMounted, watch, inject } from 'vue'
import axios from 'axios'
import Multiselect from '@suadelabs/vue3-multiselect'
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css'
const loadingSpinner = inject('loadingSpinner')
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
const showMessage = inject('showMessage')
const showError = inject('showError')

const description = ref('')
const submitted = ref(false)

const fillForm = ref(false)
const clearForm = ()=>{
    description.value = ''
}

onMounted(() => {

})

const props = defineProps({
    orderId: String
});

const emit = defineEmits(['rejected'])


const loading = ref(false)
const saveRejection = async ()=>{
    loading.value = true
        const payload =  {
      type: 'MESSAGE',
      reporter_id: JSON.parse(localStorage.getItem('user')).id,
      remarker_id : JSON.parse(localStorage.getItem('user')).id,
      source: 'LPO',        
      source_id: props.orderId,
      module: 'LPO & VOUCHERS',
      description: description.value,
      status_id: 4
    }


    try{
        await  axiosInstance.put(`approval-lists/${props.orderId}`,payload);
        if(description.value !==''){
            axiosInstance.post('logs',payload)
        }
        showMessage(`Order ID ${props.orderId} was Rejected`)
        submitted.value = true
        emit('rejected', props.orderId)
    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
        loading.value = false
    }

}

</script>