<template>
  <div
    class="modal fade mymodal"
    id="payment-request-modal"
    data-bs-backdrop="false"
    data-bs-keyboard="false"
    tabindex="-1"
    aria-labelledby="paymentRequestModalLabel"
    aria-hidden="true"
  >
    <div class="modal-dialog modal-fullscreen">
      <div class="modal-content">

        <div class="modal-header">
          <h1 class="modal-title fs-5" id="paymentRequestModalLabel">
            Service Payment For {{ payment?.description }}
          </h1>
          <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="resetForm()"></button>
        </div>

        <div class="modal-body">

          <!-- Jobcard Details Table -->
          <div v-if="payment?.jobcard" class="panel p-0">
            <div class="my-4 custom-table table3 table-responsive">
              <table class="table table-hover table-striped table-bordered">
                <tbody>
                  <tr>
                    <td><strong>Card#:</strong></td>
                    <td>00{{ payment.jobcard.id }}</td>
                    <td><strong>Date Created:</strong></td>
                    <td>{{ payment.jobcard.date_created || '---' }}</td>
                  </tr>
                  <tr>
                    <td><strong>Machine Category:</strong></td>
                    <td>{{ payment.jobcard.machine?.category?.name || '---' }}</td>
                    <td><strong>Machine:</strong></td>
                    <td>
                      {{
                        payment.jobcard.machine?.name
                          ? payment.jobcard.machine.name +
                            (payment.jobcard.machine.type_name ? ' - ' + payment.jobcard.machine.type_name : '')
                          : '---'
                      }}
                    </td>
                  </tr>
                  <tr>
                    <td><strong>Location:</strong></td>
                    <td>{{ payment.jobcard.location?.name || '---' }}</td>
                    <td><strong>Issuer:</strong></td>
                    <td>{{ payment.jobcard.issuer?.name || '---' }}</td>
                  </tr>
                  <tr>
                    <td><strong>Service Type:</strong></td>
                    <td>{{ payment.jobcard.service_type || '---' }}</td>
                    <td><strong>Status:</strong></td>
                    <td><span class="badge bg-primary">{{ payment.jobcard.status?.name || '---' }}</span></td>
                  </tr>
                  <tr>
                    <td><strong>Current KMs:</strong></td>
                    <td>
                      {{
                        payment.jobcard.current_km_of_service != null
                          ? Number(payment.jobcard.current_km_of_service).toLocaleString('en-US')
                          : '---'
                      }}
                    </td>
                    <td><strong>Next Service KMs:</strong></td>
                    <td>
                      {{
                        payment.jobcard.next_km_of_service != null
                          ? Number(payment.jobcard.next_km_of_service).toLocaleString('en-US')
                          : '---'
                      }}
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>

          <div class="d-flex me-4 mt-2">
            <div class="ms-auto">
              <button
                type="button"
                :class="request_payment ? 'btn btn-danger' : 'btn btn-primary'"
                class="my-2"
                @click="
                  request_payment = !request_payment;
                  if (!request_payment) resetForm();
                  else getUnits();
                "
                v-if="user_permissions.includes('can_request_service_payment')"
              >
                <i :class="request_payment ? 'bi bi-x-lg' : 'bi bi-plus-square'" class="fs-6"></i>
              </button>
            </div>
          </div>

          <!-- Service Payment Request Form -->
          <div v-if="request_payment" class="mt-3 my-4">
            <h6 class="text-center">Request Service Payment</h6>

            <div class="row mb-2">
              <div class="col-md-4 text-start">
                <label class="form-label">Task</label>
                <input type="text" class="form-control" placeholder="Enter Task" v-model="description" required>
              </div>

              <div class="col-md-4 text-start">
                <label class="form-label small">Unit</label>
                <multiselect
                  v-model="unit"
                  :options="unitList"
                  placeholder="Unit"
                  label="short_name"
                  :searchable="true"
                  :allow-empty="false"
                  required
                ></multiselect>
              </div>

              <div class="col-md-4 text-start">
                <label class="form-label">Quantity</label>
                <input type="number" class="form-control" placeholder="Enter quantity" step="any" v-model="quantity" required>
              </div>

              <div class="col-md-6 text-start">
                <label class="form-label">Rate</label>
                <input type="number" class="form-control" v-model="rate" required>
              </div>

              <div class="col-md-6 text-start">
                <label class="form-label">Receiver</label>
                <input type="text" class="form-control" v-model="receiver" required>
              </div>
            </div>
          </div>

          <!-- Orders Table -->
          <div class="panel p-0">
            <div v-if="loadingOrders" v-html="tableShimmer()"></div>
            <div v-else class="custom-table">
              <v-client-table :data="orders" :columns="orderColumns" :options="table_option">
                <template #status="props">
                  <span class="badge inv-status" :class="`badge-${props.row.status.color}`" style="cursor: pointer;">
                    {{ props.row.status.name }}
                  </span>
                </template>

                <template #voucher_no="props">
                  <span
                    class="badge bg-primary"
                    style="cursor: pointer;"
                    @click="
                      selectedOrder = props.row;
                      openModalOnModal('approvalChainModal', 'payment-request-modal');
                    "
                  >
                    {{ props.row.voucher_no }}
                  </span>
                </template>
              </v-client-table>
            </div>
          </div>

        </div>

        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="resetForm()">Close</button>

          <button
            v-if="request_payment"
            type="button"
            class="btn btn-primary"
            :disabled="submittingRequisition"
            @click="submitRequisition()"
          >
            <span v-if="submittingRequisition" v-html="loadingSpinner()"></span>
            <span v-else>Submit</span>
          </button>
        </div>

      </div>
    </div>
  </div>

  <approvalChainModal :OrderId="selectedOrder.voucher_no" />
</template>

<script setup>
import { ref, inject, watch } from 'vue';
import axios from 'axios';
import Multiselect from "@suadelabs/vue3-multiselect";
import "@suadelabs/vue3-multiselect/dist/vue3-multiselect.css";
import approvalChainModal from '@/views/approvalChain/components/approvalChainModal.vue';
const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;

const props = defineProps({
  payment: { type: Object, default: null }
});

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL
});

const openModalOnModal = inject('openModalOnModal');
const formatRate = inject('formatRate');
const showMessage = inject('showMessage');
const showError = inject('showError');
const loadingSpinner = inject('loadingSpinner');
const tableShimmer = inject('tableShimmer');
const user_id = JSON.parse(localStorage.getItem("user")).id;

const table_option = ref({
  perPage: 20,
  perPageValues: [20, 50, 100],
  skin: 'table table-hover table-striped',
  columnsClasses: { actions: 'actions text-center' },
  sortable: ['Sno', 'description', 'amount', 'date'],
  sortIcon: {
    base: 'sort-icon-none',
    up: 'sort-icon-asc',
    down: 'sort-icon-desc',
  },
  pagination: { nav: 'scroll', chunk: 5 },
  texts: {
    count: 'Showing {from} to {to} of {count}',
    filter: '',
    filterPlaceholder: 'Search...',
    limit: 'Results:',
  },
  resizableColumns: false,
});

const request_payment = ref(false);
const selectedOrder = ref('');

const description = ref('');
const receiver = ref('');
const unit = ref(null);
const unitList = ref([]);
const quantity = ref('');
const rate = ref('');
const submittingRequisition = ref(false);

const resetForm = () => {
  description.value = '';
  receiver.value = '';
  unit.value = null;
  quantity.value = '';
  rate.value = '';
};

const getUnits = async () => {
  try {
    const response = await axiosInstance.get('/units');
    unitList.value = response.data;
  } catch (error) {
    showError(error.message);
  }
};

const submitRequisition = async () => {
  submittingRequisition.value = true;

  const formData = new FormData();

  formData.append('requisition', JSON.stringify({
    date: new Date().toISOString().split('T')[0],
    required_date: new Date().toISOString().split('T')[0],
    description: `Payment request for ${props.payment?.description} on job card 00${props.payment?.jobcard?.id}`,
    project_id: 36,
    requester_id: user_id,
    beneficiary: receiver.value,
    approval_group_id: 9,
  }));

  formData.append('type', JSON.stringify({
    name: 'jobcard service',
    item_id: props.payment.id,
  }));

  formData.append('items', JSON.stringify([
    {
      item_id: 0,
      quantity: Number(quantity.value),
      rate: Number(rate.value),
      beneficiary: receiver.value,
      remark: description.value,
      description: description.value,
      units: unit.value.short_name,
    },
  ]));

  try {
    await axiosInstance.post('create-requisition', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
    });

    showMessage('General requisition created successfully');
    request_payment.value = false;
    resetForm();
    getServiceOrders(props.payment.id, false);
  } catch (error) {
    console.error(error);
    showError(error.message);
  } finally {
    submittingRequisition.value = false;
  }
};

const orders = ref([]);
const loadingOrders = ref(false);
const orderColumns = ref(['Sno', 'voucher_no', 'project', 'description', 'cost', 'requester', 'date', 'status']);

const getServiceOrders = async (id, showLoader = true) => {
  if (showLoader) loadingOrders.value = true;
  try {
    const response = await axiosInstance.get(`jobcard-service-orders?payment_id=${id}`);
    orders.value = response.data.map((item, index) => ({
      ...item,
      Sno: index + 1,
      voucher_no: item.order_id,
      cost: formatRate(item.cost)
    }));
  } catch (error) {
    console.log(error);
    showError(error.message);
  } finally {
    if (showLoader) loadingOrders.value = false;
  }
};

watch(
  () => props.payment,
  (row) => {
    if (row?.id) getServiceOrders(row.id);
  }
);
</script>